CREATE TYPE "QuoteStatus" AS ENUM ('DRAFT','READY_FOR_REVIEW','APPROVED','SENT','VIEWED','ACCEPTED','PAID','EXPIRED','CANCELLED');
CREATE TYPE "JobStatus" AS ENUM ('PENDING','RUNNING','COMPLETED','FAILED');
CREATE TYPE "JobType" AS ENUM ('GENERATE_PDF','SEND_EMAIL','GENERATE_IMAGE','SYNC_SHOPIFY');
CREATE TABLE "Session" ("id" TEXT PRIMARY KEY,"shop" TEXT NOT NULL,"state" TEXT NOT NULL,"isOnline" BOOLEAN NOT NULL DEFAULT false,"scope" TEXT,"expires" TIMESTAMP(3),"accessToken" TEXT NOT NULL,"userId" BIGINT,"firstName" TEXT,"lastName" TEXT,"email" TEXT,"accountOwner" BOOLEAN NOT NULL DEFAULT false,"locale" TEXT,"collaborator" BOOLEAN DEFAULT false,"emailVerified" BOOLEAN DEFAULT false);
CREATE TABLE "SeatingStyle" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"reference" TEXT NOT NULL UNIQUE,"description" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Quote" ("id" TEXT PRIMARY KEY,"reference" TEXT NOT NULL UNIQUE,"shop" TEXT NOT NULL,"status" "QuoteStatus" NOT NULL DEFAULT 'DRAFT',"customerName" TEXT NOT NULL,"customerEmail" TEXT NOT NULL,"customerTelephone" TEXT,"customerAddress" TEXT,"deliveryPostcode" TEXT,"enquiryDate" TIMESTAMP(3) NOT NULL,"enquiryReference" TEXT,"internalNotes" TEXT,"seatingStyleId" TEXT REFERENCES "SeatingStyle"("id"),"currentRevisionNumber" INTEGER NOT NULL DEFAULT 0,"shopifyDraftOrderId" TEXT,"shopifyInvoiceUrl" TEXT,"pdfObjectKey" TEXT,"createdBy" TEXT NOT NULL,"updatedBy" TEXT NOT NULL,"approvedAt" TIMESTAMP(3),"sentAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "QuoteRevision" ("id" TEXT PRIMARY KEY,"quoteId" TEXT NOT NULL REFERENCES "Quote"("id") ON DELETE CASCADE,"revisionNumber" INTEGER NOT NULL,"specification" JSONB NOT NULL,"pricing" JSONB NOT NULL,"seatingFullPricePence" INTEGER NOT NULL,"deliveryCostPence" INTEGER NOT NULL,"additionalOptionsTotalPence" INTEGER NOT NULL,"grandTotalPence" INTEGER NOT NULL,"currency" TEXT NOT NULL DEFAULT 'GBP',"vatInclusive" BOOLEAN NOT NULL DEFAULT true,"createdBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "QuoteRevision_quoteId_revisionNumber_key" UNIQUE("quoteId","revisionNumber"));
CREATE TABLE "QuoteCounter" ("shop" TEXT PRIMARY KEY,"nextNumber" INTEGER NOT NULL DEFAULT 1);
CREATE TABLE "Job" ("id" TEXT PRIMARY KEY,"quoteId" TEXT NOT NULL REFERENCES "Quote"("id") ON DELETE CASCADE,"type" "JobType" NOT NULL,"status" "JobStatus" NOT NULL DEFAULT 'PENDING',"idempotencyKey" TEXT NOT NULL UNIQUE,"payload" JSONB NOT NULL,"attempts" INTEGER NOT NULL DEFAULT 0,"maxAttempts" INTEGER NOT NULL DEFAULT 3,"availableAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lockedAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"lastError" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "Job_status_availableAt_idx" ON "Job"("status","availableAt");
CREATE TABLE "DeliveryAttempt" ("id" TEXT PRIMARY KEY,"quoteId" TEXT NOT NULL,"revisionNumber" INTEGER NOT NULL,"recipientHash" TEXT NOT NULL,"providerMessageId" TEXT,"status" TEXT NOT NULL,"errorCode" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "DeliveryAttempt_quoteId_revisionNumber_recipientHash_key" UNIQUE("quoteId","revisionNumber","recipientHash"));
CREATE TABLE "WebhookReceipt" ("id" TEXT PRIMARY KEY,"topic" TEXT NOT NULL,"shop" TEXT NOT NULL,"processedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
